import type { ComponentProps } from "react";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
  DialogTrigger,
} from "./dialog";

/** A side sheet: the `Dialog` (native modal, focus trap, Escape) presented as a panel from an edge. */
export const Drawer = Dialog;
export const DrawerTrigger = DialogTrigger;
export const DrawerTitle = DialogTitle;
export const DrawerDescription = DialogDescription;
export const DrawerFooter = DialogFooter;
export const DrawerClose = DialogClose;

export type DrawerContentProps = Omit<ComponentProps<typeof DialogContent>, "position"> & {
  /** The edge it slides from. Default `right`. */
  side?: "left" | "right" | "bottom";
};

export function DrawerContent({ side = "right", ...rest }: DrawerContentProps) {
  return <DialogContent {...rest} position={side} />;
}
